import org.elasticsearch.index.query.QueryBuilders;
import org.elasticsearch.index.query.BoolQueryBuilder;

public class SearchQueryBuilderExample {
    public BoolQueryBuilder buildComplexSearchQuery(String searchTerm, String category, double maxPrice) {
        BoolQueryBuilder boolQuery = QueryBuilders.boolQuery();

        // Match query for full-text description with fuzzy tolerance
        boolQuery.must(QueryBuilders.matchQuery("description", searchTerm).fuzziness("AUTO"));

        // Term query for exact category match
        boolQuery.filter(QueryBuilders.termQuery("category.keyword", category));

        // Range query for price filtering
        boolQuery.filter(QueryBuilders.rangeQuery("price").lte(maxPrice));

        // Should query to boost items that are currently in stock
        boolQuery.should(QueryBuilders.termQuery("inStock", true).boost(2.0f));

        return boolQuery;
    }
}
